"""Render the standalone experiment page from the public, credential-free ledger."""
import json, html
from pathlib import Path
root = Path(__file__).resolve().parents[1]
d = json.loads((root/'data/cofi-android-harmony.json').read_text())
e = html.escape
rows = []
md = ['# Cofi · Android → HarmonyOS', '', '实验规划 · 2026-10-30 · 11 组。历史迁移自报完成 6 组，待运行 5 组。', '', '**自报完成不代表独立验收通过。** 本轮仅登记计划与历史证据，尚未启动新实验。', '', '| 模型 / ID | Harness | 迁移状态 | 独立验收 | 结果镜像（本地 Tart） |', '|---|---|---|---|---|']
for i, x in enumerate(d['experiments'], 1):
    done = x['migration'] == '迁移自报完成'
    image = '<code>'+e(x['result_image'])+'</code><small>本地克隆 · 远程地址待补</small>' if x['result_image'] else '<span class="muted">待产出</span>'
    if x['image_url']:
        assert x['image_url'].startswith('https://')
        image += '<a href="'+e(x['image_url'],quote=True)+'">下载镜像</a>'
    rows.append(f'''<tr data-state="{'done' if done else 'planned'}" data-harness="{e(x['harness'])}"><td class="number">{i:02}</td><td><strong>{e(x['model_family'])}</strong><small>{e(x['model_id'])}</small></td><td>{e(x['harness'])}<small>{e(x['harness_version'])}</small></td><td><span class="badge {'done' if done else ''}">{e(x['migration'])}</span><small>{e(x['evaluation'])}</small></td><td>{image}</td><td class="notes">{e(x['notes'])}</td></tr>''')
    md.append('| '+' | '.join([x['model_family']+' / '+x['model_id'],x['harness']+' '+x['harness_version'],x['migration'],x['evaluation'],'`'+x['result_image']+'` · 远程地址待补' if done else '待产出'])+' |')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cofi 实验计划 · HMBot Benchmark</title>
<style>
:root{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#182b32;background:#f4f6f3}*{box-sizing:border-box}body{margin:0}header{padding:22px 5vw;border-bottom:1px solid #dce4df;display:flex;justify-content:space-between;gap:20px;font-size:13px}a{color:#186c59}main{max-width:1540px;margin:auto;padding:52px 5vw}h1{font-size:clamp(30px,4vw,48px);letter-spacing:-1.5px;margin:12px 0 16px}h2{font-size:19px;margin:0 0 12px}.eyebrow{font-size:12px;font-weight:700;color:#27745f;letter-spacing:2px}.intro{max-width:780px;line-height:1.8;color:#587078}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:32px 0}.metric{padding:24px;background:white;border:1px solid #dce4df;border-radius:12px}.metric b{font-size:36px;display:block;margin-bottom:8px}.metric span{font-size:13px;color:#607477}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:28px 0 14px}select,input{font:inherit;background:white;border:1px solid #c7d6cc;border-radius:7px;padding:10px;max-width:100%}label{font-size:13px}#count{margin-left:auto;color:#607477;font-size:13px}.table-wrap{overflow:auto;border:1px solid #dce4df;border-radius:12px;background:white}table{border-collapse:collapse;width:100%;min-width:1000px;text-align:left}th{font-size:11px;color:#667b7b;letter-spacing:1px;background:#eaf0eb;padding:16px}td{font-size:13px;padding:20px 16px;border-top:1px solid #edf1ee;vertical-align:top}small{display:block;font-size:11px;color:#607477;line-height:1.6;margin-top:7px}code{font-size:11px;overflow-wrap:anywhere}.badge{display:inline-block;background:#edf0f4;color:#596a7b;border-radius:6px;padding:5px 8px;font-size:11px;white-space:nowrap}.badge.done{background:#e3f2e8;color:#236a4b}.notes{max-width:220px;line-height:1.7;color:#607477}.number{color:#8a9998}.muted{color:#8a9998}.details{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:28px}.detail{padding:25px;background:#fff;border:1px solid #dce4df;border-radius:12px;font-size:13px;line-height:1.9}.detail ul{padding-left:20px}footer{margin:28px 0;color:#607477;font-size:12px;line-height:1.8}@media(max-width:700px){main{padding:30px 20px}.metrics{gap:8px}.metric{padding:16px}.metric b{font-size:28px}.details{grid-template-columns:1fr}header{padding:20px}.toolbar label{width:100%}#count{margin-left:0}}[hidden]{display:none!important}
</style><header><strong>HMBOT / BENCHMARK LAB</strong><span>EXPERIMENT PLAN · 2026.10.30</span></header><main><div class="eyebrow">COFI / CROSS-PLATFORM MIGRATION</div><h1>Android → HarmonyOS</h1><p class="intro">五种模型，两个 Harness，再加一组 Codex + GPT 对照。先锁定实验组合与历史产物，再统一推进迁移和独立测试。本页仅登记规划，不启动新实验。</p>
<div class="metrics"><div class="metric"><b>11</b><span>实验组合</span></div><div class="metric"><b>6</b><span>历史迁移自报完成</span></div><div class="metric"><b>5</b><span>待运行组合</span></div></div>
<div class="toolbar"><label>状态 <select id="state"><option value="all">全部状态</option><option value="done">迁移自报完成</option><option value="planned">待运行</option></select></label><label>Harness <select id="harness"><option value="all">全部 Harness</option><option>DevEco Code</option><option>Claude Code</option><option>Codex CLI</option></select></label><label>搜索 <input id="search" type="search" placeholder="模型 / 镜像名称"></label><span id="count" aria-live="polite">11 组</span></div>
<div class="table-wrap"><table><caption hidden>11 组 Cofi 安卓到鸿蒙实验</caption><thead><tr><th>#</th><th>模型 / 标识</th><th>HARNESS / 版本</th><th>迁移与验收</th><th>结果镜像</th><th>备注</th></tr></thead><tbody>ROWS</tbody></table></div>
<div class="details"><section class="detail"><h2>实验口径</h2><ul><li>固定 Cofi Android 源码提交 <code>e3212d7090b0dd3d81ec5a31cb0b0641f68c865a</code>。</li><li>新实验建议每组独立 Tart、8 CPU / 8 GiB、图形化与可见 Terminal；每轮先归档再释放设备。</li><li>启动前锁定模型准确 ID、reasoning effort、Harness 版本、prompt SHA 与基础镜像。GPT 型号待确定。</li><li>历史 Claude Code 为 2.1.267；不能将不同版本、prompt 或设备接口的结果当成完全等条件实验。是否复用历史结果或统一重测待锁定。</li></ul></section><section class="detail"><h2>状态与镜像说明</h2><ul><li>“迁移自报完成”只表示 agent 已交付，不表示测试通过。</li><li>10/27 历史 Claude Code 测试存在定位和观测阻塞，不展示为有效综合分数；Pro 采用 10/28 重测，未套用旧版评分。</li><li>已核对六个结果克隆本地存在。当前没有已确认的远程下载地址或 OCI digest；本地名称不是公开镜像 URL。</li><li>下载地址字段预留在 JSON 中。发布前须另行准备已去除凭据的结果镜像，本页不上传 VM 磁盘或原始日志。</li></ul></section></div><footer>范围外历史项：OpenCode + GLM、Codex + GLM、DSH + GLM、双账号 Flash 实验不计入这 11 组。<br><a href="../data/cofi-android-harmony.json">实验数据 JSON</a> · <a href="cofi-android-harmony.md">GitHub 文档版</a> · 更新时间：2026-10-30（Asia/Shanghai）</footer></main>
<script>const rows=[...document.querySelectorAll('tbody tr')];const state=document.querySelector('#state'),harness=document.querySelector('#harness'),search=document.querySelector('#search');function filter(){let n=0;for(const row of rows){row.hidden=!((state.value==='all'||row.dataset.state===state.value)&&(harness.value==='all'||row.dataset.harness===harness.value)&&row.textContent.toLowerCase().includes(search.value.trim().toLowerCase()));if(!row.hidden)n++}document.querySelector('#count').textContent=n+' / 11 组'}for(const el of [state,harness,search])el.addEventListener('input',filter);</script></html>'''.replace('ROWS',''.join(rows))
(root/'experiments/cofi-android-harmony.html').write_text(page)
md += ['', '## 实验口径与待锁定项', '', '- 固定源码：`'+d['source_commit']+'`。建议每组独立 Tart，8 CPU / 8 GiB，图形化和可见 Terminal。', '- GPT 的准确型号、reasoning effort，以及待运行组的模型和 Harness 版本须在启动前锁定。', '- 六组完成记录为历史证据；是否复用或统一重测待锁定。历史 Claude Code 为 2.1.267，基础镜像与 prompt 存在差异，不能宣称完全等条件对照。', '- DeepSeek Pro 采用 10/28 重测；10/27 对旧版的测试不混入。其他历史测试存在定位/观测阻塞，不展示为有效综合分。', '- 镜像栏为已核实存在的本地 Tart 克隆名称；远程下载地址尚未提供。发布结果镜像前需去除凭据。本页未上传磁盘或原始日志。', '- OpenCode + GLM、Codex + GLM、DSH + GLM 和双账号实验不计入本矩阵。', '', '[结构化数据](../data/cofi-android-harmony.json) · [HTML 页面](cofi-android-harmony.html)', '']
(root/'experiments/cofi-android-harmony.md').write_text('\n'.join(md))
